#include <iostream>

int main() {
    // Prompt and read first integer
    std::cout << "Enter first integer: ";
    int number1{0};
    std::cin >> number1;

    // Prompt and read second integer
    std::cout << "Enter second integer: ";
    int number2{0};
    std::cin >> number2;

    // Chaining insertion and inline computation
    std::cout << "Sum is " << number1 + number2 << std::endl;

    return 0;
}

#include <iostream>

int main() {
    int a{7};
    int b{4};

    // Nondestructive reads of a and b
    int quotient = a / b;
    int remainder = a % b;

    std::cout << "Quotient: " << quotient << std::endl;
    std::cout << "Remainder: " << remainder << std::endl;

    // Destructive write to a
    a = quotient + remainder;
    std::cout << "New a: " << a << std::endl;

    return 0;
}
